        return self.#flags.pipelined;
}

pub inline fn isSimple(self: *const MySQLQuery) bool {
        return self.#flags.simple;
}

pub inline fn isBigintSupported(self: *const MySQLQuery) bool {
        return self.#flags.bigint;
}

pub inline fn getResultMode(self: *const MySQLQuery) SQLQueryResultMode {
        return self.#flags.result_mode;
}

pub inline fn markAsPrepared(self: *MySQLQuery) void {
        if ((self.#status == .pending)) {
            if (self.#statement) |statement| {
                _ = &statement;
                if ((((statement.status == .parsing) and (statement.params.len == statement.params_received)) and (statement.statement_id > 0))) {
                    statement.status = .prepared;
                }
            }
        }
}

pub inline fn getStatement(self: *const MySQLQuery) ?*MySQLStatement {
        return self.#statement;
}
const JSGlobalObject = bun.jsc.JSGlobalObject;
const JSValue = bun.jsc.JSValue;
const debug = bun.Output.scoped(.MySQLQuery, .visible);

pub fn BindAndExecuteCtx(comptime WriterType: type) type {
        return struct {
        query_ptr: *MySQLQuery,
        writer: WriterType,
        statement: *MySQLStatement,
        globalObject: *JSGlobalObject,
        binding_value: JSValue,
        columns_value: JSValue,
        result: AnyMySQLError.Error!void,

        pub fn run(ctx: *@This(), roots: *bun.jsc.MarkedArgumentBuffer) callconv(.c) void {
            ctx.result = ctx.query_ptr.bindAndExecuteImpl(ctx.writer, ctx.statement, ctx.globalObject, ctx.binding_value, ctx.columns_value, roots);
        }
    };
}
